e", "price_field", "price", "source", "kind", "direction"], "title": "Trigger", "type": "object"}, "TriggerSource": {"additionalProperties": false, "properties": {"timeframe": {"title": "Timeframe", "type": "string"}, "bar_index": {"minimum": 0, "title": "Bar Index", "type": "integer"}, "open_time_ms": {"minimum": 0, "title": "Open Time Ms", "type": "integer"}, "close_time_ms": {"minimum": 0, "title": "Close Time Ms", "type": "integer"}}, "required": ["timeframe", "bar_index", "open_time_ms", "close_time_ms"], "title": "TriggerSource", "type": "object"}}, "additionalProperties": false, "properties": {"schema": {"const": "brooks.trade-intent.v2", "title": "Schema", "type": "string"}, "role": {"const": "TRADER", "title": "Role", "type": "string"}, "decision": {"enum": ["ENTER_LONG", "ENTER_SHORT", "NO_TRADE"], "title": "Decision", "type": "string"}, "symbol": {"title": "Symbol", "type": "string"}, "decision_time_ms": {"minimum": 0, "title": "Decision Time Ms", "type": "integer"}, "market_context": {"anyOf": [{"additionalProperties": true, "type": "object"}, {"type": "null"}], "title": "Market Context"}, "setup": {"anyOf": [{"$ref": "#/$defs/Setup"}, {"type": "null"}]}, "decision_timeframe": {"anyOf": [{"type": "string"}, {"type": "null"}], "title": "Decision Timeframe"}, "context_timeframes_used": {"items": {"type": "string"}, "title": "Context Timeframes Used", "type": "array"}, "entry_mechanism": {"enum": ["continuation", "breakout", "breakout_pullback", "reversal", "none", "unclear"], "title": "Entry Mechanism", "type": "string"}, "trigger": {"anyOf": [{"$ref": "#/$defs/Trigger"}, {"type": "null"}]}, "invalidation": {"anyOf": [{"$ref": "#/$defs/PriceReference"}, {"type": "null"}]}, "evidence_for": {"items": {"type": "string"}, "minItems": 1, "title": "Evidence For", "type": "array"}, "evidence_against": {"items": {"type": "string"}, "minItems": 1, "title": "Evidence Against", "type": "array"}, "qualitative_confidence": {"enum": ["high", "medium", "low"], "title": "Qualitative Confidence", "type": "string"}, "uncertainty": {"items": {"type": "string"}, "minItems": 1, "title": "Uncertainty", "type": "array"}, "conditions_that_change_market_read": {"items": {"type": "string"}, "minItems": 1, "title": "Conditions That Change Market Read", "type": "array"}}, "required": ["schema", "role", "decision", "symbol", "decision_time_ms", "market_context", "setup", "decision_timeframe", "context_timeframes_used", "entry_mechanism", "trigger", "invalidation", "evidence_for", "evidence_against", "qualitative_confidence", "uncertainty", "conditions_that_change_market_read"], "title": "TradeIntentV2", "type": "object"}
Input: {"decision_time_ms": 1789934399999, "macro_contexts": {"D1": {"context": {"always_in": "long", "always_in_relevance": "medium", "breakout_mode": true, "confidence": "medium", "decision_time_ms": 1789862399999, "directional_pressure": "bull", "evidence_against": ["The window high 2771.00 (1787270400000) is 25 bars old and untouched; price is still below the 2680.00 range high on a closing basis, so the breakout leg remains an attempt inside the range, not accepted structure.", "The last bar was rejected at 2700.00, leaving an upper tail of about 67 points, and the prior 2680.00 attempt (1789084800000) closed roughly 165 points below its high; the same zone has produced two visible sellers' reactions, an incipient double top.", "1789430400000 is a wide bear bar (open 2513.91, low 2358.62, close 2397.10) that erased several bull closes in one bar, showing two-sided trade with bears still able to produce strong bars inside the range.", "A 29-bar overlapping range after a near-vertical spike is equally consistent with a climactic spike followed by distribution; the spike's 2771.00 tail bar closed only at 2515.30, well below its high."], "evidence_for": ["The most recent close 2632.98 is the highest close of the supplied 120 bars, and the last two bars are consecutive bull bars that take out the prior six bars' highs and the 2557.46 inner ceiling.", "Whole-window structure is a bull sequence of higher swing lows (1368.42 -> 1512.91 -> 1551.60 -> 1694.74 -> 2357.18) with the 2358.62 low (1789430400000) holding above 2357.18, so the 29-bar sideways stretch follows a strong bull spike and reads as a bull flag rather than a completed top.", "Range pullbacks have been shallow relative to the 1905.63-2771.00 spike: most range closes stay above the spike's midpoint near 2338, and each push down to the 2357-2395 area has been bought back into the 2440-2530 zone.", "Each successive upper test has closed higher (2514.72 at 1789084800000 versus 2632.98 at 1789776000000), i.e. sellers at 2680-2700 have not produced a lower close or an accepted break back down."], "missing_information": [], "observations": ["120 closed D1 bars, first open 2066.43 (1779494400000), last bar open 2612.03 / high 2700 / low 2604.75 / close 2632.98 (close_time_ms 1789862399999).", "Bars 1-15 of the window decline from high 2143.61 (1779494400000) to low 1368.42 (1780704000000); the 1780704000000 bar has range 1368.42-1599.27 and closes 1568.55 in the upper part of that range with a long lower tail.", "Higher lows follow the 1368.42 low: 1512.91 (1782432000000), 1551.60 (1782777600000), 1694.74 (1783296000000); rising highs reach 1959.37 (1785024000000), then ~12 bars overlap between roughly 1820 and 1960 (1785456000000-1787011200000).", "Three-bar bull spike from 1905.63 to 2771.00: opens/closes 1916.51/2252.16, 2252.20/2326.32, 2326.31/2515.30 at 1787097600000, 1787184000000, 1787270400000; the 2771.00 high leaves a large upper tail on the third bar.", "Since 1787356800000 the market has been sideways: 29 bars between low 2357.18 (1788307200000) and spike highs 2680.00 (1789084800000) and 2700.00 (1789776000000), with most closes between roughly 2390 and 2540 and an inner ceiling at 2557.46 (1787788800000).", "Two separate upside spike attempts above that inner ceiling: 1789084800000 (open 2436.83, high 2680.00, close 2514.72, upper tail ~165) and 1789689600000-1789776000000 (close 2612.02, then high 2700.00 with close 2632.98, upper tail ~67).", "1789430400000 is a large bear bar inside the same range: open 2513.91, low 2358.62, close 2397.10, i.e. a wide body closing near its low.", "The last close 2632.98 is the highest close in the supplied 120-bar window, and the 2700.00 high is still below the window high 2771.00."], "phase": "breakout-spike", "primary_regime": "bull-trend", "role": "CONTEXT_ANALYST", "schema": "brooks.market-context.v2", "structures": [{"description": "Opening bear leg of the window: 15 bars of lower highs and lower lows from 2143.61 into an accelerating sell-off that reaches 1368.42 (1780704000000), where the bar closes at 1568.55 in the upper 72% of its 1368.42-1599.27 range, a long-lower-tail reversal bar.", "end_time_ms": 1780790399999, "kind": "climax", "lower_boundary": "1368.42", "start_time_ms": 1779494400000, "upper_boundary": "2143.61"}, {"description": "Recovery and uptrend from the 1368.42 low: higher lows at 1512.91 (1782432000000) and 1551.60 (1782777600000) with rising highs into 1959.37 (1785024000000), followed by an overlapping ~1820-1960 pause (1785456000000-1787011200000) that holds well above the 1368.42 origin.", "end_time_ms": 1787097599999, "kind": "channel", "lower_boundary": "1368.42", "start_time_ms": 1780790400000, "upper_boundary": "1959.37"}, {"description": "Three-bar bull spike: bars at 1787097600000, 1787184000000 and 1787270400000 run from 1905.63 to 2771.00 with closes 2252.16, 2326.32 and 2515.30; the 2771.00 extreme is a spike high with a large upper tail and has not been retested.", "end_time_ms": 1787270400000, "kind": "breakout", "lower_boundary": "1905.63", "start_time_ms": 1787097600000, "upper_boundary": "2771"}, {"description": "Trading range after the spike: 29 bars from 1787356800000 to the last bar, bounded by 2357.18 (1788307200000) and the 2680.00 spike high (1789084800000), with heavy overlap, most closes between roughly 2390 and 2540, and an inner ceiling near 2557.46 (1787788800000).", "end_time_ms": 1789862399999, "kind": "range", "lower_boundary": "2357.18", "start_time_ms": 1787356800000, "upper_boundary": "2680"}, {"description": "Two upside spike attempts into the same 2680.00-2700.00 area (1789084800000: high 2680.00, close 2514.72; 1789776000000: high 2700.00, close 2632.98) separated by a sell-off to 2358.62 (1789430400000). The pair is a possible double top at the range high, though the second attempt closes 118 points higher than the first.", "end_time_ms": 1789862399999, "kind": "two-sided", "lower_boundary": "2358.62", "start_time_ms": 1789084800000, "upper_boundary": "2700"}, {"description": "Two-bar bull leg / breakout attempt: 1789689600000 (open 2446.22, high 2643.52, close 2612.02) and 1789776000000 (open 2612.03, high 2700.00, low 2604.75, close 2632.98). Price lifts above the 2557.46 inner ceiling and prints the window's highest close, but has not yet closed above the 2680.00 range high.", "end_time_ms": 1789862399999, "kind": "breakout", "lower_boundary": "2436.87", "start_time_ms": 1789689600000, "upper_boundary": "2700"}], "symbol": "ETH-USDT", "timeframe": "D1", "transition_conditions": ["Acceptance above the 2680.00 range high, e.g. a close above it followed by another bar closing above 2700.00, would confirm the range breakout and support the bull-trend / breakout-spike read.", "A close back below 2557.46 and into the 2390-2540 range body would negate the breakout attempt and restore an intact trading range between 2357.18 and 2680.00.", "A close below 2357.18 would be a bear breakout from the 29-bar range and would shift the structural read away from the bull flag toward a bear or transition classification.", "Failure to exceed 2680.00 over the next few bars while forming a lower high below 2700.00 would leave the two-sided/double-top interpretation as the strongest alternative and reduce Always-In relevance to low."], "window_bars": 120}, "freshness": "current"}, "H4": {"context": {"always_in": "long", "always_in_relevance": "medium", "breakout_mode": false, "confidence": "medium", "decision_time_ms": 1789919999999, "directional_pressure": "bull", "evidence_against": ["From 2358.62 (1789488000000) to 2700.00 (1789804800000) the market made rising lows and rising highs together for about 23 bars (lows 2370.54 -> 2435.71 -> 2495.82 -> 2578.44; highs 2425.53 -> 2519.81 -> 2585.50 -> 2700.00), which is trend structure, not two-sided trade.", "The base breakout shows acceptance: two large bull bars (1789732800000, 1789747200000) plus 13 consecutive closes above the base top 2519.81, with no close back below it.", "The pullback is shallow for a range top (only 38.6% of the last leg, stopping 48.35 above 2519.81) and the final bar closes at its high 2611.00 above the two preceding bars' highs, which reads as a bull-flag-style pause; holding above 2568.16 would argue the upper boundary is being broken rather than defended."], "evidence_for": ["Window net change is only +144.48 (+5.9%) against a high-low span of 342.82 (~14%), and the market crossed that full height repeatedly (2357.18 -> 2537.57 -> 2411.04 -> 2680.00 -> 2358.62 -> 2700.00), which is two-sided range behavior rather than sustained trend.", "The 2700.00 print (1789804800000) exceeds the prior high 2680.00 (1789128000000) by only 20.00 (~0.7%), and no close in the window exceeded 2680.00 (maximum close 2640.01, bar at 1789819200000), so the upper boundary is not accepted.", "The earlier push to 2680.00 (1789128000000) was retraced in full to 2358.62 (1789488000000), showing sellers near the upper boundary; 2357.18 and 2358.62 form a near-equal double bottom that has defined the lower boundary.", "The current leg is a single sustained advance (2358.62 -> 2700.00) with one shallow pause; inside this range context it remains a leg/breakout attempt until the upper boundary is accepted with closes beyond it."], "missing_information": [], "observations": ["Window of 120 closed H4 bars (open_time 1788192000000 to 1789919999999): open 2466.52, last close 2611.00 (+144.48, ~+5.9%), high 2700.00 (bar open_time 1789804800000), low 2357.18 (bar open_time 1788336000000); high-low span 342.82 (~14% of price).", "Swing sequence: 2357.18 low (1788336000000) -> 2537.57 high (1788508800000) -> 2411.04 low (1789041600000) -> 2680.00 high (1789128000000) -> 2358.62 low (1789488000000) -> 2700.00 high (1789804800000); each opposing swing retraced most of the prior one.", "Bar at 1789128000000 is a wide bull bar (O 2457.12, H 2680.00, L 2444.19, C 2555.52) with a 124.48 upper tail; that advance was fully retraced to 2358.62 by the bar at 1789488000000.", "Bars from 1789660800000 to 1789718400000 form a base between 2370.54 (low, 1789689600000) and 2519.81 (high, 1789718400000) with rising highs; the two bars at 1789732800000 and 1789747200000 are large bull bars (ranges 89.68 and 63.55) closing near their highs at 2578.60 and 2636.28.", "Every close since the bar at 1789732800000 (13 closes, 2578.60 through 2611.00) is above the base top 2519.81, i.e., above the breakout level.", "Bar at 1789804800000 printed 2700.00 but closed 2638.49, 61.51 below its high, in the lower half of its 77.33 range; no close in the window exceeded 2680.00 (highest close 2640.01, bar at 1789819200000).", "Pullback from 2700.00 to 2568.16 (low, 1789891200000) equals 131.84, a 38.6% retracement of the 2358.62->2700.00 leg, and holds 48.35 above the breakout level 2519.81; the bar at 1789862400000 closed near its low (2586.68 vs low 2569.80).", "Last seven bars traded between 2568.16 and 2658.79 with small overlapping ranges (range 14.14 at 1789819200000; 17.04 at 1789891200000); the final bar (O 2577.69, H 2611.00, L 2571.48, C 2611.00) closes at its high, above the highs of the two preceding bars (2586.73, 2585.20)."], "phase": "range", "primary_regime": "trading-range", "role": "CONTEXT_ANALYST", "schema": "brooks.market-context.v2", "structures": [{"description": "Broad 120-bar two-sided range bounded by the window extremes; price traveled the full height more than once (2357.18 -> 2537.57 -> 2411.04 -> 2680.00 -> 2358.62 -> 2700.00) with each swing retracing most of the prior one, while net change was only +5.9%. The last swing is a bull leg testing the upper boundary.", "end_time_ms": 1789919999999, "kind": "range", "lower_boundary": "2357.18", "start_time_ms": 1788192000000, "upper_boundary": "2700.00"}, {"description": "Near-equal double bottom at the lower boundary: 2357.18 (bar at 1788336000000) and 2358.62 (bar at 1789488000000); the second test held and launched the current 341.38-point advance.", "end_time_ms": 1789488000000, "kind": "swing", "lower_boundary": "2357.18", "start_time_ms": 1788336000000, "upper_boundary": null}, {"description": "Bull breakout above the bars 1789660800000-1789718400000 base top 2519.81, driven by two wide bull bars (1789732800000, 1789747200000) with follow-through: 13 consecutive closes above the breakout level and a pullback low 2568.16 that held 48.35 above it. This is a confirmed breakout of the recent base, but not of the 2680.00 upper range boundary.", "end_time_ms": 1789919999999, "kind": "breakout", "lower_boundary": "2519.81", "start_time_ms": 1789732800000, "upper_boundary": null}, {"description": "Potential reversal structure at the upper boundary, not established: 2700.00 (1789804800000) exceeds the prior high 2680.00 (1789128000000) by 20.00 and closes 61.51 below its high, and the bar at 1789862400000 is a bear bar closing near its low at 2586.68. No strong bear reversal bar or second leg down has printed, so this is only a possible top of the range.", "end_time_ms": 1789919999999, "kind": "mtr-like", "lower_boundary": null, "start_time_ms": 1789128000000, "upper_boundary": "2700.00"}, {"description": "Five-to-seven-bar pullback/flag from 2700.00 to 2568.16 with overlapping small-range bars (includes 14.14 and 17.04 range bars), retracing 38.6% of the last leg and ending with the final bar closing at its high 2611.00 above the two prior bars' highs.", "end_time_ms": 1789919999999, "kind": "other", "lower_boundary": "2568.16", "start_time_ms": 1789819200000, "upper_boundary": "2658.79"}], "symbol": "ETH-USDT", "timeframe": "H4", "transition_conditions": ["Acceptance above the range top: two or more closes above 2680.00, and especially a close above 2700.00 with follow-through, would shift the read from range to a confirmed bull breakout/trend continuation.", "Failure at the top: a lower high below 2700.00 followed by a strong bear bar closing below 2568.16 (and then below the breakout level 2519.81